<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Database;use App\Services\SpecialCategoryService;
Auth::requireAdmin();$roundId=(int)($_GET['round_id']??0);$pdo=Database::connection();$s=$pdo->prepare("SELECT dance_style,division FROM bdc_scoring_rounds WHERE id=:id AND round_type='final' LIMIT 1");$s->execute(['id'=>$roundId]);$round=$s->fetch();if(!$round){http_response_code(404);exit('Final round not found.');}$dance=(string)($round['dance_style']??'bachata');$division=(string)($round['division']??'');if($dance==='salsa'&&in_array($division,['salsa_rising','salsa_open','salsa_invitational'],true)){header('Location: special-publish-salsa.php?round_id='.$roundId,true,303);exit;}if($dance==='salsa'){header('Location: publish-salsa.php?round_id='.$roundId,true,303);exit;}if(SpecialCategoryService::isSpecial($division)){header('Location: special-publish.php?round_id='.$roundId,true,303);exit;}header('Location: publish.php?round_id='.$roundId,true,303);exit;
